import React from 'react';

import {
  mapEquipSetListItemToAddDto,
  mapEquipSetListItemToUpdateDto,
} from '@apps/Hiking/@mappers/equip.mapper';
import {
  addOrEditEquipSet,
  getBackpacks,
  getOneEquipSetById,
} from '@apps/Hiking/@services/equip.service';
import { IBackpack, IEquipSetListItem } from '@apps/Hiking/@types/equip.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import { showModal } from '@ui-kit/Modal';
import PohSelect from '@ui-kit/Select';

interface IEquipSetEditParamsProps {
  data: IEquipSetListItem;
  onSave: (data: IEquipSetListItem) => void;
}

const EquipSetEditParams: React.FC<IEquipSetEditParamsProps> = ({ data, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);

  const [isPreparing, setIsPreparing] = React.useState(false);
  const [errPreparing, setErrPreparing] = React.useState<Error>();

  const [error, setError] = React.useState<Error>();
  const [addData, setAddData] = React.useState<IEquipSetListItem>(data);

  const [backpacks, setBackpacks] = React.useState<IBackpack[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsPreparing(true);
        const res = await getBackpacks();
        setBackpacks(res);
      } catch (er) {
        setErrPreparing(er as Error);
      } finally {
        setIsPreparing(false);
      }
    };

    start();
  }, []);

  const handleInputChange =
    <K extends keyof IEquipSetListItem>(field: keyof IEquipSetListItem) =>
    (value: IEquipSetListItem[K]) => {
      setAddData((fd) => ({
        ...(fd as IEquipSetListItem),
        [field]: value,
      }));
    };

  return (
    <form
      style={{ minWidth: 420, gap: 12 }}
      onSubmit={async (e) => {
        e.preventDefault();
        try {
          setIsLoading(true);

          if (!addData.id) {
            const { id } = await addOrEditEquipSet(mapEquipSetListItemToAddDto(addData));
            onSave({ ...addData, id });
          } else {
            await addOrEditEquipSet(mapEquipSetListItemToUpdateDto(addData));
            await getOneEquipSetById(+addData.id);
            onSave(addData);
          }
        } catch (er) {
          setError(er as Error);
        } finally {
          setIsLoading(false);
        }
      }}
      className="d-flex flex-column"
    >
      <PohInput
        horizontal
        required
        label="Название"
        value={addData.name}
        onChange={handleInputChange('name')}
        placeholder="Название сборки"
        disabled={isLoading}
      />
      <PohInput
        horizontal
        required
        label="Описание"
        value={addData.description}
        onChange={handleInputChange('description')}
        placeholder="Описание сборки"
        disabled={isLoading}
        type={InputTypes.textarea}
      />

      <PohSelect
        horizontal
        required
        label="Рюкзак"
        allowEmpty
        placeholder="Рюкзак не выбран"
        options={backpacks.map((b) => ({ value: b.id.toString(), label: b.name }))}
        value={addData.backpack ? addData.backpack.id.toString() : null}
        onChange={(strValOrNull: string | null) =>
          handleInputChange('backpack')(
            backpacks.find((x) => x.id.toString() === strValOrNull) ?? null,
          )
        }
        disabled={isLoading || isPreparing || !!errPreparing}
      />

      <footer className="text-end pt-2 mb-n3">
        {error && <PohAlert variant={AlertVariant.Danger}>{error.message}</PohAlert>}
        <PohButton type="submit">Сохранить</PohButton>
      </footer>
    </form>
  );
};

export const editEquipSetParams = (data: IEquipSetListItem): Promise<IEquipSetListItem> => {
  return new Promise((res) => {
    showModal({
      title: data.id && +data.id > 0 ? 'Редактирование сборки' : 'Добавление сборки',
      children: (clos) => (
        <EquipSetEditParams
          data={data}
          onSave={(r) => {
            res(r);
            clos();
          }}
        />
      ),
    });
  });
};
